SQL = "-- M1-R03 cross-relation invariants validated on direct PostgreSQL writes.\n-- Lock parent membership rows so concurrent membership changes cannot invalidate\n-- a case/assignment while a referencing record is inserted.\nCREATE OR REPLACE FUNCTION public.m1_validate_case_links()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE o uuid; r text;\nBEGIN\n SELECT m.organization_id,m.role INTO o,r FROM public.accounts_membership m\n WHERE m.id=NEW.employee_id FOR SHARE;\n IF o IS DISTINCT FROM NEW.organization_id OR r IS DISTINCT FROM 'EMPLOYEE' THEN\n    RAISE EXCEPTION 'Invalid case employee membership' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND;$$;\nCREATE TRIGGER m1_case_links BEFORE INSERT OR UPDATE OF organization_id,employee_id\nON public.onboarding_onboardingcase FOR EACH ROW EXECUTE FUNCTION public.m1_validate_case_links();\n\nCREATE OR REPLACE FUNCTION public.m1_validate_assignment_links()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE o uuid; r text; case_org uuid;\nBEGIN\n SELECT c.organization_id INTO case_org FROM public.onboarding_onboardingcase c\n WHERE c.id=NEW.case_id FOR SHARE;\n SELECT m.organization_id,m.role INTO o,r FROM public.accounts_membership m\n WHERE m.id=NEW.member_id FOR SHARE;\n IF o IS DISTINCT FROM case_org OR r IS DISTINCT FROM NEW.role\n    OR NEW.role NOT IN ('HR','IT','MANAGER')\n    OR NEW.effective_from > clock_timestamp() THEN\n    RAISE EXCEPTION 'Invalid case assignment membership/role/start' USING ERRCODE='23514';\n END IF;\n IF NEW.assigned_by_id IS NOT NULL THEN\n    SELECT organization_id INTO o FROM public.accounts_membership WHERE id=NEW.assigned_by_id FOR SHARE;\n    IF o IS DISTINCT FROM case_org THEN\n       RAISE EXCEPTION 'Invalid assigning owner organization' USING ERRCODE='23514';\n    END IF;\n END IF;\n RETURN NEW;\nEND;$$;\nCREATE TRIGGER m1_assignment_links BEFORE INSERT OR UPDATE OF case_id,member_id,role,effective_from,assigned_by_id\nON public.onboarding_caseassignment FOR EACH ROW EXECUTE FUNCTION public.m1_validate_assignment_links();\n\nCREATE OR REPLACE FUNCTION public.m1_validate_member_change()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n IF (NEW.organization_id,NEW.role) IS DISTINCT FROM (OLD.organization_id,OLD.role) THEN\n   IF EXISTS (SELECT 1 FROM public.onboarding_onboardingcase WHERE employee_id=NEW.id)\n      OR EXISTS (SELECT 1 FROM public.onboarding_caseassignment WHERE member_id=NEW.id) THEN\n     RAISE EXCEPTION 'Cannot modify role/organization of referenced membership' USING ERRCODE='23514';\n   END IF;\n END IF;\n RETURN NEW;\nEND;$$;\nCREATE TRIGGER m1_member_links BEFORE UPDATE OF organization_id,role\nON public.accounts_membership FOR EACH ROW EXECUTE FUNCTION public.m1_validate_member_change();\n"
